CREATE TABLE IF NOT EXISTS gateway_schema (id INT PRIMARY KEY CHECK (id=1), version INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS gateway_storage_state (id INT PRIMARY KEY CHECK (id=1), migration_state VARCHAR(16) NOT NULL CHECK (migration_state IN ('PENDING','READY')), migration_source VARCHAR(200), ready_at BIGINT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS gateway_profiles (id VARCHAR(100) PRIMARY KEY, digest CHAR(64) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS accounts (id VARCHAR(36) PRIMARY KEY, username VARCHAR(32) UNIQUE NOT NULL, role VARCHAR(8) NOT NULL CHECK(role IN ('USER','ADMIN')), balance BIGINT NOT NULL CHECK(balance>=0), salt VARBINARY(16) NOT NULL, password_hash VARBINARY(32) NOT NULL, iterations INT NOT NULL CHECK(iterations>=600000), created_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS sessions (token_hash CHAR(64) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, expires_at BIGINT NOT NULL, CONSTRAINT sessions_account_fk FOREIGN KEY(user_id) REFERENCES accounts(id), INDEX sessions_expiry(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS adjustments (id VARCHAR(36) PRIMARY KEY, admin_id VARCHAR(36) NOT NULL, user_id VARCHAR(36) NOT NULL, delta BIGINT NOT NULL, reason VARCHAR(500) NOT NULL, balance_after BIGINT NOT NULL CHECK(balance_after>=0), created_at BIGINT NOT NULL, CONSTRAINT adjustments_admin_fk FOREIGN KEY(admin_id) REFERENCES accounts(id), CONSTRAINT adjustments_account_fk FOREIGN KEY(user_id) REFERENCES accounts(id), INDEX adjustments_page(created_at,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS quota_events (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, kind VARCHAR(24) NOT NULL, reference_id VARCHAR(36) NOT NULL, delta BIGINT NOT NULL, balance_after BIGINT NOT NULL CHECK(balance_after>=0), created_at BIGINT NOT NULL, CONSTRAINT quota_account_fk FOREIGN KEY(user_id) REFERENCES accounts(id), UNIQUE KEY quota_reference(user_id,kind,reference_id), INDEX quota_user_page(user_id,created_at,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS orders (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, request_id VARCHAR(36) NOT NULL, package_id VARCHAR(64) NOT NULL, units BIGINT NOT NULL CHECK(units>0), price_cents BIGINT, status VARCHAR(24) NOT NULL CHECK(status='PENDING_PAYMENT'), created_at BIGINT NOT NULL, CONSTRAINT orders_account_fk FOREIGN KEY(user_id) REFERENCES accounts(id), UNIQUE KEY order_request(user_id,request_id), INDEX orders_user_page(user_id,created_at,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS grade_requests (user_id VARCHAR(36) NOT NULL, request_id VARCHAR(36) NOT NULL, fingerprint CHAR(64) NOT NULL, model_id VARCHAR(200) NOT NULL, state VARCHAR(24) NOT NULL CHECK(state IN ('PREPARED','DISPATCHING','SUCCEEDED','FAILED','NOT_DISPATCHED','UNKNOWN')), charged BOOLEAN NOT NULL, response_json LONGTEXT, error_code VARCHAR(64), created_at BIGINT NOT NULL, profile_id VARCHAR(100), policy_revision BIGINT, CONSTRAINT requests_account_fk FOREIGN KEY(user_id) REFERENCES accounts(id), PRIMARY KEY(user_id,request_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS gateway_model_policy (id INT PRIMARY KEY CHECK(id=1), revision BIGINT NOT NULL CHECK(revision>=0), profile_id VARCHAR(100), model_id VARCHAR(200), CHECK((revision=0 AND profile_id IS NULL AND model_id IS NULL) OR (revision>0 AND profile_id IS NOT NULL AND model_id IS NOT NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS model_policy_audit (id VARCHAR(36) PRIMARY KEY, admin_id VARCHAR(36) NOT NULL, previous_profile_id VARCHAR(100), profile_id VARCHAR(100) NOT NULL, previous_model_id VARCHAR(200), model_id VARCHAR(200) NOT NULL, previous_revision BIGINT NOT NULL, revision BIGINT NOT NULL UNIQUE, reason VARCHAR(500) NOT NULL, created_at BIGINT NOT NULL, CONSTRAINT policy_admin_fk FOREIGN KEY(admin_id) REFERENCES accounts(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS rubric_generation_requests (user_id VARCHAR(36) NOT NULL, request_id VARCHAR(36) NOT NULL, fingerprint CHAR(64) NOT NULL, model_id VARCHAR(200) NOT NULL, state VARCHAR(24) NOT NULL CHECK(state IN ('PREPARED','DISPATCHING','SUCCEEDED','FAILED','NOT_DISPATCHED','UNKNOWN')), charged BOOLEAN NOT NULL, response_json LONGTEXT, error_code VARCHAR(64), created_at BIGINT NOT NULL, profile_id VARCHAR(100) NOT NULL, policy_revision BIGINT NOT NULL, CONSTRAINT rubric_requests_account_fk FOREIGN KEY(user_id) REFERENCES accounts(id), PRIMARY KEY(user_id,request_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS gateway_rubric_model_policy (id INT PRIMARY KEY CHECK(id=1), revision BIGINT NOT NULL CHECK(revision>=0), profile_id VARCHAR(100), model_id VARCHAR(200), CHECK((revision=0 AND profile_id IS NULL AND model_id IS NULL) OR (revision>0 AND profile_id IS NOT NULL AND model_id IS NOT NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS rubric_model_policy_audit (id VARCHAR(36) PRIMARY KEY, admin_id VARCHAR(36) NOT NULL, previous_profile_id VARCHAR(100), profile_id VARCHAR(100) NOT NULL, previous_model_id VARCHAR(200), model_id VARCHAR(200) NOT NULL, previous_revision BIGINT NOT NULL, revision BIGINT NOT NULL UNIQUE, reason VARCHAR(500) NOT NULL, created_at BIGINT NOT NULL, CONSTRAINT rubric_policy_admin_fk FOREIGN KEY(admin_id) REFERENCES accounts(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
